WITH fixes(pos,why) AS (VALUES (3,'Correto. O art. 37, XVI, a, da Constituição mantém a possibilidade de acumulação de dois cargos de professor, desde que respeitadas as condições constitucionais.'),(9,'Correto. O art. 37, XVI, da Constituição parte da proibição de acumular cargos remunerados, admitindo somente as exceções previstas no próprio dispositivo e sob condições.'),(10,'Correto. O art. 37, XVI, da Constituição exige compatibilidade de horários nas hipóteses excepcionais de acumulação remunerada de cargos públicos.'),(12,'Correto. O art. 37, XVI, a, da Constituição admite dois cargos de professor, mas a acumulação não dispensa compatibilidade de horários.'),(15,'Correto. O art. 37, XVI, c, da Constituição admite dois cargos ou empregos privativos de profissionais de saúde com profissões regulamentadas, respeitada a compatibilidade de horários.'),(16,'Errado. A compatibilidade de horários continua sendo exigida para acumular dois cargos de professor, conforme o art. 37, XVI, da Constituição.'),(17,'Correto. O art. 37, XVII, da Constituição estende a proibição de acumular a empregos e funções e a entidades da administração indireta nele indicadas.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='constitucional-acumulacao-ec138-casos' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;